mapper.select:
SELECT
n.*,
IFNULL(nu.is_read, 0) AS is_read,
u.real_name AS publisher_name
FROM biz_notice n
LEFT JOIN sys_user u ON n.publisher_id = u.id
LEFT JOIN biz_notice_user nu ON n.id = nu.notice_id AND nu.user_id = #{currentUserId}

    n.is_deleted = 0

        AND n.title LIKE CONCAT('%', #{title}, '%')


        AND n.type = #{type}


        AND n.status = #{status}


        AND n.visibility = #{visibility}



        AND IFNULL(nu.is_read, 0) = #{isRead}
        AND n.type IN (3, 4)



        AND u.real_name LIKE CONCAT('%', #{publisherName}, '%')


ORDER BY (n.type IN (3, 4) AND (nu.is_read = 0 OR nu.is_read IS NULL)) DESC, n.publish_time DESC, n.create_time DESC

SELECT * FROM biz_notice
WHERE id IN

    #{id}
